47	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
48	import org.springframework.samples.petclinic.rest.validation.HouseholdDuplicateValidator;
49	import org.springframework.samples.petclinic.rest.validation.HouseholdIdGenerator;
50	import org.springframework.samples.petclinic.rest.validation.IdentityDuplicateValidator;
51	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
52	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
53	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
54	import org.springframework.samples.petclinic.rest.validation.RegistrationDateValidator;
55	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
