65	
66	import jakarta.transaction.Transactional;
67	
68	/**
69	 * @author Vitaliy Fedoriv
70	 */
71	
72	@RestController
73	@CrossOrigin(exposedHeaders = "errors, content-type")
74	@RequestMapping("/api")
75	public class OwnerRestControllerV1 implements OwnersApi {
76	
77	    private final ClinicService clinicService;
78	
79	    private final OwnerMapper ownerMapper;
80	
81	    private final PetMapper petMapper;
82	
83	    private final VisitMapper visitMapper;
84	
85	    private final OwnerFieldsValidator ownerFieldsValidator;
86	
87	    private final PostcodeValidator postcodeValidator;
88	
89	    private final RegistrationDateValidator registrationDateValidator;
90	
91	    private final HouseholdDuplicateValidator householdDuplicateValidator;
92	
93	    private final IdentityDuplicateValidator identityDuplicateValidator;
94	
95	    private final HouseholdIdGenerator householdIdGenerator;
96	
97	    private final TelephoneNormalizer telephoneNormalizer;
98	
99	    private final EmailNormalizer emailNormalizer;
100	
101	    private final AddressNormalizer addressNormalizer;
102	
103	    private final CustomerCodeGenerator customerCodeGenerator;
104	
105	    private final NamesakeCounter namesakeCounter;
106	
107	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
108	
109	    private final OwnerAuditLogger ownerAuditLogger;
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper,
115	                                 OwnerFieldsValidator ownerFieldsValidator,
116	                                 PostcodeValidator postcodeValidator,
117	                                 RegistrationDateValidator registrationDateValidator,
118	                                 HouseholdDuplicateValidator householdDuplicateValidator,
119	                                 IdentityDuplicateValidator identityDuplicateValidator,
120	                                 HouseholdIdGenerator householdIdGenerator,
121	                                 TelephoneNormalizer telephoneNormalizer,
122	                                 EmailNormalizer emailNormalizer,
123	                                 AddressNormalizer addressNormalizer,
124	                                 CustomerCodeGenerator customerCodeGenerator,
125	                                 NamesakeCounter namesakeCounter,
126	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator,
127	                                 OwnerAuditLogger ownerAuditLogger) {
128	        this.clinicService = clinicService;
129	        this.ownerMapper = ownerMapper;
130	        this.petMapper = petMapper;
131	        this.visitMapper = visitMapper;
132	        this.ownerFieldsValidator = ownerFieldsValidator;
133	        this.postcodeValidator = postcodeValidator;
134	        this.registrationDateValidator = registrationDateValidator;
135	        this.householdDuplicateValidator = householdDuplicateValidator;
136	        this.identityDuplicateValidator = identityDuplicateValidator;
137	        this.householdIdGenerator = householdIdGenerator;
138	        this.telephoneNormalizer = telephoneNormalizer;
139	        this.emailNormalizer = emailNormalizer;
140	        this.addressNormalizer = addressNormalizer;
141	        this.customerCodeGenerator = customerCodeGenerator;
142	        this.namesakeCounter = namesakeCounter;
143	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
144	        this.ownerAuditLogger = ownerAuditLogger;
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
150	        Collection<Owner> owners;
151	        if (lastName != null) {
152	            owners = this.clinicService.findOwnerByLastName(lastName);
153	        } else {
154	            owners = this.clinicService.findAllOwners();
155	        }
156	        if (owners.isEmpty()) {
157	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
158	        }
159	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
165	        Owner owner = this.clinicService.findOwnerById(ownerId);
166	        if (owner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
175	        if (ownerFieldsDto != null) {
176	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
177	        }
178	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
179	        if (!missingFields.isEmpty()) {
180	            throw new MissingOwnerFieldsException(missingFields);
181	        }
182	        HttpHeaders headers = new HttpHeaders();
183	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
184	        Collection<Owner> sameLastName =
185	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
186	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
187	        List<Owner> householdMembers = assignHousehold(owner, ownerFieldsDto, sameLastName);
188	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
189	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
190	        postcodeValidator.validate(owner.getPostcode(), owner.getCity());
191	        rejectIfDuplicateIdentity(owner);
192	        joinHousehold(owner, householdMembers);
193	        registrationDateValidator.validate(owner.getRegistrationDate());
194	        if (owner.getRegistrationDate() == null) {
195	            owner.setRegistrationDate(LocalDate.now());
196	        }
197	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
198	        LocalDate registrationDate = owner.getRegistrationDate();
199	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
200	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
201	            throw new DailyOwnerLimitException(registrationDate);
202	        }
203	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
204	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
205	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
206	            throw new CityOwnerLimitException(owner.getCity());
207	        }
208	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity());
209	        owner.setCustomerCode(customerCodeGenerator.generate(
210	            region, owner.getTelephone(), owner.getLastName()));
211	        this.clinicService.saveOwner(owner);
212	        ownerAuditLogger.ownerCreated(owner);
213	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
214	        headers.setLocation(UriComponentsBuilder.newInstance()
215	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
216	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
217	    }
