31	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
32	    @Mapping(target = "identityKey", expression = "java(formatIdentityKey(owner))")
33	    @Mapping(target = "sharesHousehold", ignore = true)
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    /**
37	     * Builds an owner's display name from the stored names, formatted as
38	     * {@code "LastName, FirstName"}.
39	     */
40	    default String formatDisplayName(Owner owner) {
41	        return owner.getLastName() + ", " + owner.getFirstName();
42	    }
43	
44	    /**
45	     * Builds an owner's initials from the stored names as the upper-cased first
46	     * letters of the first and last name, dot-separated with a trailing dot,
47	     * e.g. {@code "J.S."}.
48	     */
49	    default String formatInitials(Owner owner) {
50	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
51	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
52	    }
53	
54	    /**
55	     * Builds an owner's membership number from its stored fields, formatted
56	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of
57	     * the registration date's year, e.g. {@code "NSW-3F2A9C1E-M26"}. Returns
58	     * {@code null} when either the customer code or registration date is absent.
